      --text: #102033;
      --muted: #5b6b7f;
      --border: #d7dfeb;
      --border-strong: #9fb0c5;
      --accent: #2563eb;
      --accent-strong: #1d4ed8;
      --focus: #0f62fe;
      --shadow: 0 18px 50px #10203314;
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top, #eaf1ff 0, #f5f7fb 40%, #eef3f9 100%);
    }

    body {
      margin: 0;
      min-height: 100vh;
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      top: 0.75rem;
      left: 0.75rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
      transform: translateY(-160%);
      transition: transform 160ms ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      display: grid;
      place-items: center;
      min-height: 100vh;
      padding: 5rem 1.25rem 2rem;
    }

    .card {
      width: min(100%, 42rem);
      background: var(--surface);
      border: 1px solid #e4eaf2;
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 4vw, 2.5rem);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.75rem, 3vw, 2.25rem);
      line-height: 1.15;
    }

    .subtitle {
      margin: 0 0 1.5rem;
      color: var(--muted);
      max-width: 60ch;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: linear-gradient(180deg, #ffffff 0%, var(--surface-alt) 100%);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-width: 0;
    }

    legend {
      padding: 0;
      margin: 0 0 1rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .hint {
      margin: 0 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .options {
      display: grid;
      gap: 0.75rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .option {
      display: block;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface);
      transition: border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
    }

    .option:hover {
      border-color: var(--border-strong);
    }

    .option:has(input:focus-visible) {
      box-shadow: 0 0 0 4px #dbeafe;
      border-color: var(--focus);
    }

    .option-label {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      padding: 1rem 1rem 1rem 1.1rem;
      cursor: pointer;
      font-weight: 600;
      color: var(--text);
    }

    input[type="radio"] {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.875rem;
      margin-top: 1.25rem;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      font: inherit;
      font-weight: 700;
      color: #ffffff;
      background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
      box-shadow: 0 10px 24px #2563eb33;
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.03);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.25rem;
      }

      .form-field {
        padding: 1rem;
      }

      .option-label {
        padding: 0.9rem;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-alt: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --border-strong: ButtonBorder;
        --accent: Highlight;
        --accent-strong: Highlight;
        --focus: Highlight;
      }

      .card,
      .form-field,
      .option,
      button,
      .skip-link {
        forced-color-adjust: auto;
        box-shadow: none;
      }

      .option:has(input:focus-visible),
      button:focus-visible,
      .skip-link:focus {
        outline: 2px solid Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Notification settings</h1>
      <p class="subtitle">Choose how you'd like to receive updates from the product.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-status">
            <legend>How do you prefer to receive notifications?</legend>
            <p class="hint" id="notification-help">Select one option before continuing.</p>

            <ul class="options" role="list">
              <li class="option">
                <label class="option-label" for="email">
                  <input type="radio" id="email" name="notificationPreference" value="Email" required>
                  <span>Email</span>
                </label>
              </li>
              <li class="option">
                <label class="option-label" for="sms">
                  <input type="radio" id="sms" name="notificationPreference" value="SMS">
                  <span>SMS</span>
                </label>
              </li>
              <li class="option">
                <label class="option-label" for="push">
                  <input type="radio" id="push" name="notificationPreference" value="Push Notifications">
                  <span>Push Notifications</span>
                </label>
              </li>
            </ul>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>

        <p class="status" id="notification-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const status = document.getElementById("notification-status");
    const firstRadio = document.getElementById("email");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!form.checkValidity()) {
        form.reportValidity();
        firstRadio.focus();
        status.textContent = "Choose a notification preference to continue.";
        return;
      }

      const selected = form.notificationPreference.value;
      status.textContent = `Saved preference: ${selected}.`;
    });
  </script>
</body>
</html>
