<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Notification settings</h1>
      <p class="subtitle">Choose how you'd like to receive updates from the product.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-status">
            <legend>How do you prefer to receive notifications?</legend>
            <p class="hint" id="notification-help">Select one option before continuing.</p>

            <ul class="options">
              <li class="option">
                <label class="option-label" for="email">
                  <input type="radio" id="email" name="notificationPreference" value="Email" required>
                  <span>Email</span>
                </label>
              </li>
              <li class="option">
                <label class="option-label" for="sms">
                  <input type="radio" id="sms" name="notificationPreference" value="SMS">
                  <span>SMS</span>
                </label>
              </li>
              <li class="option">
                <label class="option-label" for="push">
                  <input type="radio" id="push" name="notificationPreference" value="Push Notifications">
                  <span>Push Notifications</span>
                </label>
              </li>
            </ul>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>

        <p class="status" id="notification-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const status = document.getElementById("notification-status");
    const firstRadio = document.getElementById("email");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!form.checkValidity()) {
        form.reportValidity();
        firstRadio.focus();
        status.textContent = "Choose a notification preference to continue.";
        return;
      }

      const selected = form.notificationPreference.value;
      status.textContent = `Saved preference: ${selected}.`;
    });
  </script>
</body>
